import {normalize,dot,activate,mse} from './ai-foundation-model.js';
const $=id=>document.getElementById(id),fmt=v=>v.toFixed(4);
const topics={
 data:{title:'ข้อมูลเป็นตัวเลข · ภาพที่โมเดลอ่าน',intro:'ภาพขาวดำจิ๋ว 3×3 มีค่าความสว่าง 9 ค่า ไม่ใช่รูปที่โมเดลมองเหมือนคน ลองเปลี่ยนหนึ่ง Pixel แล้วดูตำแหน่งเดียวกันใน Vector หลังหาร 255 การจัดเรียงต้องเหมือนกันตอนฝึกและตอนใช้งาน',terms:[['Pixel','จุดภาพหนึ่งจุด มีค่าความสว่าง'],['Grayscale','ภาพขาวดำ ตัวอย่างนี้ดำ0 / ขาว255'],['Flatten','เรียงซ้าย→ขวาทีละแถว จากภาพเป็นรายการ'],['Normalize','ตัวอย่างนี้หาร255 ให้ค่าอยู่ช่วง0–1 ไม่ใช่การทำ normalization ทุกชนิด']],limits:'ภาพสมมติ 3×3 grayscale แถวก่อนคอลัมน์ ไม่มีตัวรู้จำรูป ไม่ใช่ MNIST และยังไม่แปลงข้อความเป็น Token (เรียนภายหลัง)',source:'https://www.3blue1brown.com/lessons/neural-networks/',steps:['อ่านความสว่าง 9 จุด','เรียงแถว → Vector','หารแต่ละค่าด้วย 255'],task:'กด Pixel ลำดับ1 (มุมซ้ายบน) จนเป็น255 เล่นหรือเดินจนขั้น3 ดูสมาชิกแรกกลายเป็น1.0000 สมาชิกอื่นไม่ย้ายตำแหน่ง แล้วตรวจภารกิจ'},
 vector:{title:'Vector และ Dot product · คูณคู่แล้วรวม',intro:'Vector คือรายการตัวเลขที่มีลำดับ Dot product จับคู่สมาชิกตำแหน่งเดียวกัน คูณแล้วบวกทั้งหมด ได้ตัวเลขหนึ่งค่า กลไกนี้อยู่ใน Neuron ก่อนบวก Bias เส้นและแท่งในภาพเป็นค่าคำนวณ ไม่ใช่ Packet',terms:[['Vector','รายการตัวเลขที่ตำแหน่งมีความหมาย'],['Dimension','จำนวนสมาชิกของ Vector'],['Dot product','x₁w₁+x₂w₂ เมื่อมีสองสมาชิก'],['Matrix','ตารางหลายแถว แต่ละแถวคูณ Vector ได้หนึ่งเอาต์พุต']],limits:'ใช้2มิติเพื่ออ่านง่าย ไม่ใช่ embedding ภาษา ตาราง Matrix ตัวอย่างใช้แถวที่สอง [−0.3,0.7] คงที่ ยังไม่สอนการแปลงฐานหรือ eigenvector',source:'https://numpy.org/doc/stable/reference/generated/numpy.dot.html',steps:['จับคู่ x กับ w','คูณสมาชิกตำแหน่งเดียวกัน','รวม → Dot product และ Matrix × Vector'],task:'ตั้ง x=[1,0.5] และ w=[0.8,−0.4] ดู Dot=0.6 จากนั้นเปลี่ยน w₂ เป็น0.4 จนขั้น3 ดู Dot=1.0 (เพิ่ม0.4) แล้วตรวจภารกิจ'},
 activation:{title:'Activation · ไม่ใช่ทุกชั้นเป็นเส้นตรง',intro:'Neuron รวมค่าได้ z จากนั้น Activation เปลี่ยน z เป็น a ถ้าทุกชั้นเป็นแค่การแปลงเชิงเส้นกับ Bias การซ้อนกันยังยุบเป็นการแปลงแบบ affine เดียวได้ ความไม่เชิงเส้นทำให้โครงข่ายแทนรูปแบบซับซ้อนได้มากขึ้น แต่ไม่ได้รับประกันว่าฝึกสำเร็จ',terms:[['z','ค่าผลรวมก่อน Activation'],['a / Activation','ค่าหลังผ่านฟังก์ชัน'],['ReLU','max(0,z): ค่าลบเป็น0 ค่าบวกคงเดิม'],['Sigmoid / tanh','Sigmoidอยู่0–1; tanhอยู่−1–1 ไม่ใช่ probability โดยตัวฟังก์ชันอย่างเดียว']],limits:'กราฟจริงอยู่บนระนาบในฉาก3D ไม่ใช่ surface3ตัวแปร เลือก Linear/ReLU/Sigmoid/tanh เพื่อเทียบค่า ไม่จำลอง Training หรืออ้าง ReLU differentiable ที่0',source:'https://docs.pytorch.org/docs/stable/generated/torch.nn.ReLU.html',steps:['อ่าน z ก่อน Activation','เคลื่อนตามกราฟ f(z)','อ่าน a = f(z)'],task:'เลือก ReLU ใช้ z=−1 จนขั้น3 ดู a=0 แล้วเปลี่ยน z=1 จนขั้น3 ดู a=1 ต้องดูครบสองกรณีก่อนตรวจภารกิจ'},
 loss:{title:'Loss · ทายผิดเท่าไร วัดอย่างไร',intro:'เปรียบเทียบค่าทำนายกับ Target ตัวอย่าง 2 ค่า เราหักลบ ยกกำลังสอง แล้วเฉลี่ยเป็น MSE ค่าคลาดเคลื่อนบวกกับลบจึงไม่หักล้างกัน ค่านี้เป็นเป้าหมายการฝึก ไม่ใช่ Accuracy',terms:[['Prediction (ŷ)','ค่าตัวเลขที่โมเดลทาย'],['Target (y)','ค่าคำตอบที่ใช้เปรียบเทียบ'],['Error','ค่าทำนาย−Target อาจเป็นบวกหรือลบ'],['MSE','ค่าเฉลี่ยของ squared errors; หน่วยเป็นกำลังสองของหน่วยข้อมูล']],limits:'Regressionสองเอาต์พุต Target=[1,−0.5] ไม่มี Cross entropy ในต้นแบบนี้ ไม่ใช่ตัวชี้วัดเดียวของทุกงาน และLossต่ำบนชุดฝึกไม่ได้พิสูจน์ว่าข้อมูลใหม่แม่น',source:'https://docs.pytorch.org/docs/stable/generated/torch.nn.MSELoss.html',steps:['Prediction เทียบ Target','Error → ยกกำลังสอง','เฉลี่ย → MSE'],task:'ใช้ค่าตั้งต้น ŷ=[0,0.5] ดู Errors=[−1,1] และ MSE=1 แม้ Errorรวมเป็น0 จากนั้นตั้ง ŷ=[1,−0.5] จนขั้น3 ให้ Loss=0 แล้วตรวจภารกิจ'}
};
let s,scene,rev=0;const seen=new Set();
function fresh(topic){return {topic,step:0,playing:false,speed:Number($('speed').value),revision:++rev,pixels:[0,128,255,255,128,0,0,255,128],x:[1,.5],w:[.8,-.4],z:-1,kind:'relu',pred:[0,.5],target:[1,-.5]};}
function values(){s.normalized=normalize(s.pixels);s.dot=dot(s.x,s.w);s.a=activate(s.z,s.kind);s.mse=mse(s.pred,s.target);}
function render(){values();const t=topics[s.topic];$('scene-title').textContent=t.steps[s.step];$('step').textContent=`${s.step+1}/3 · ${t.steps[s.step]}`;$('play').textContent=s.playing?'Ⅱ หยุด':'▶ เล่น';$('previous').disabled=s.step===0;$('next').disabled=s.step===2;
 if(s.step===2){if(s.topic==='activation')seen.add(`${s.kind}:${s.z}`);if(s.topic==='loss'&&s.pred[0]===0&&s.pred[1]===.5)seen.add('opposite');}
 if(s.topic==='data')$('result').innerHTML=`<p class="metric">Vector = [${s.normalized.map(v=>v.toFixed(2)).join(', ')}]</p><p>ตำแหน่ง1: ${s.pixels[0]} ÷ 255 = ${fmt(s.normalized[0])}</p><p>ลำดับ: แถว1คอลัมน์1 → 2 → 3 → แถว2 → แถว3 ไม่มีการเพิ่มข้อมูลใหม่</p>`;
 if(s.topic==='vector')$('result').innerHTML=`<p class="metric">x · w = ${fmt(s.dot.sum)}</p><p>${s.x.map((v,i)=>`(${v} × ${s.w[i]})`).join(' + ')} = ${s.dot.products.map(fmt).join(' + ')}</p><p>Matrix [[${s.w.join(', ')}], [−0.3, 0.7]] × x = [${fmt(s.dot.sum)}, ${fmt(dot(s.x,[-.3,.7]).sum)}]</p>`;
 if(s.topic==='activation')$('result').innerHTML=`<p class="metric">${s.kind}(${s.z}) = ${fmt(s.a)}</p><p>Linear ${fmt(activate(s.z,'linear'))} · ReLU ${fmt(activate(s.z,'relu'))} · Sigmoid ${fmt(activate(s.z,'sigmoid'))} · tanh ${fmt(activate(s.z,'tanh'))}</p><p>เมื่อเปลี่ยนฟังก์ชัน Input z เดิมไม่เปลี่ยน ภาพแสดงฟังก์ชันที่เลือกเท่านั้น</p>`;
 if(s.topic==='loss')$('result').innerHTML=`<p class="metric">MSE = ${fmt(s.mse.loss)}</p><p>Errors [${s.mse.errors.map(fmt)}] → Squares [${s.mse.squares.map(fmt)}]</p><p>(${s.mse.squares.map(fmt).join(' + ')}) ÷ 2 = ${fmt(s.mse.loss)}</p><p>Errorรวม ${fmt(s.mse.errors.reduce((a,b)=>a+b,0))} ไม่ใช่ Loss และอาจหักล้างกัน</p>`;
}
function changed(){s.step=0;s.playing=false;s.revision++;$('feedback').textContent='ปรับค่าแล้ว เดินขั้นเพื่อสังเกตผลใหม่';render();}
function numeric(label,value,fn,min=-2,max=2){const l=document.createElement('label');l.textContent=label;const i=document.createElement('input');Object.assign(i,{type:'number',min,max,step:.1,value});l.append(i);i.addEventListener('input',()=>{const v=Number(i.value);if(i.value===''||!Number.isFinite(v)||v<min||v>max){i.setAttribute('aria-invalid','true');$('feedback').textContent=`ใช้ค่าระหว่าง ${min} และ ${max} · ยังใช้ค่าถูกต้องล่าสุด`;return;}i.removeAttribute('aria-invalid');fn(v);changed();});$('inputs').append(l);}
function open(topic){s=fresh(topic);const t=topics[topic];for(const [id,key]of [['title','title'],['intro','intro'],['task','task'],['limits','limits']])$(id).textContent=t[key];$('source').href=t.source;$('terms').innerHTML=t.terms.map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('');$('inputs').replaceChildren();$('feedback').textContent='';document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.topic===topic)));
 if(topic==='data'){const grid=document.createElement('div');grid.className='pixels';s.pixels.forEach((v,j)=>{const b=document.createElement('button');const paint=()=>{b.textContent=s.pixels[j];b.setAttribute('aria-label',`Pixel ${j+1}: ${s.pixels[j]}`);b.style.setProperty('--gray',`rgb(${s.pixels[j]},${s.pixels[j]},${s.pixels[j]})`);b.style.setProperty('--ink',s.pixels[j]<128?'white':'black');};paint();b.onclick=()=>{s.pixels[j]=[0,128,255][([0,128,255].indexOf(s.pixels[j])+1)%3];paint();changed();};grid.append(b);});$('inputs').append(grid);}
 if(topic==='vector'){s.x.forEach((v,i)=>numeric(`x${i+1}`,v,n=>s.x[i]=n));s.w.forEach((v,i)=>numeric(`w${i+1}`,v,n=>s.w[i]=n));}
 if(topic==='activation'){numeric('z ก่อน Activation',s.z,v=>s.z=v,-3,3);const l=document.createElement('label');l.textContent='Activation';const sel=document.createElement('select');['relu','sigmoid','tanh','linear'].forEach(k=>sel.add(new Option(k,k)));sel.onchange=()=>{s.kind=sel.value;changed();};l.append(sel);$('inputs').append(l);}
 if(topic==='loss')s.pred.forEach((v,i)=>numeric(`Prediction ${i+1}`,v,n=>s.pred[i]=n));render();
}
function advance(){if(s.step<2)s.step++;else s.playing=false;render();}
document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>open(b.dataset.topic));$('next').onclick=()=>{s.playing=false;advance();};$('previous').onclick=()=>{s.playing=false;s.step=Math.max(0,s.step-1);render();};$('play').onclick=()=>{if(!s.playing&&s.step===2)s.step=0;s.playing=!s.playing;render();};$('reset').onclick=()=>open(s.topic);$('view').onclick=()=>scene?.resetView();$('speed').onchange=()=>s.speed=Number($('speed').value);
$('check').onclick=()=>{if($('inputs').querySelector('[aria-invalid=true]')){$('feedback').textContent='แก้ช่องตัวเลขที่ไม่ถูกต้องก่อนตรวจภารกิจ';return;}const ok=s.step===2&&(s.topic==='data'?s.pixels[0]===255:s.topic==='vector'?s.x[0]===1&&s.x[1]===.5&&s.w[0]===.8&&s.w[1]===.4:s.topic==='activation'?seen.has('relu:-1')&&seen.has('relu:1'):seen.has('opposite')&&s.mse.loss===0);$('feedback').textContent=ok?'✓ ทดลองครบตามภารกิจแล้ว อธิบายได้ไหมว่าค่าเปลี่ยนเพราะอะไร':'ยังไม่ครบ · ทำตามค่าที่กำหนดและเดินจนขั้น3 ก่อนตรวจ';};
document.querySelectorAll('nav a').forEach((a,i)=>a.href+=['#neuron','#forward','#gradient'][i]);
const trainingLink=document.createElement('a');trainingLink.href='ai-training.html';trainingLink.textContent='09 Batch/Epoch → 10 Validation/Overfitting ↗';document.querySelector('nav').append(trainingLink);
const requested=location.hash.slice(1);open(Object.hasOwn(topics,requested)?requested:'data');try{const {mountFoundationScene}=await import('./ai-foundation-scene.js');scene=mountFoundationScene($('stage'),()=>s,advance);}catch(e){$('fallback').hidden=false;$('play').disabled=true;$('feedback').textContent='ภาพ 3D ไม่พร้อม แต่ค่าคำนวณ/เดินขั้นด้วยมือยังใช้งานได้';}addEventListener('pagehide',()=>scene?.dispose());
